raw.text:
`:root {
  --text: #0f172a;
  --muted: #334155;
  --summary-light: #7c8798;
  --heading: #0b1220;
  --header-bg: #0f274d;
  --right-bg: #edf4ff;
  --right-text: #0f274d;
}
* { box-sizing: border-box; }
html, body {
  margin: 0;
  padding: 0;
  color: var(--text);
  font-family: Aptos, "Gill Sans MT", "Gill Sans", Calibri, "Trebuchet MS", sans-serif;
  line-height: 1.22;
  font-size: 10pt;
}
.resume {
  max-width: 8.5in;
  margin: 0 auto;
  padding: 0.28in 0.32in;
}
.header {
  display: grid;
  grid-template-columns: 1fr 88px;
  gap: 10px;
  align-items: start;
  margin-bottom: 8px;
  background: var(--header-bg);
  border: 1px solid #0b1f3f;
  padding: 10px 10px 8px;
}
.header-main {
  text-align: center;
}
.name {
  margin: 0;
  font-size: 22pt;
  line-height: 1.05;
  color: #f8fbff;
}
.label {
  margin: 3px 0 0;
  font-size: 10.4pt;
  color: #e6f0ff;
  font-style: italic;
}
.layout {
  display: grid;
  grid-template-columns: 1.7fr 1fr;
  gap: 0.16in;
  align-items: start;
}
.right-panel {
  background: var(--right-bg);
  color: var(--right-text);
  padding: 8px 8px 6px;
  line-height: 1.14;
}
.right-panel .section-title {
  color: var(--right-text);
}
.right-panel .compact-list li,
.right-panel .contact-list li,
.right-panel .skill-group,
.right-panel a {
  color: var(--right-text);
}
.right-panel .compact-list li,
.right-panel .contact-list li,
.right-panel .skill-group,
.right-panel .compact-sub li {
  font-size: 9.15pt;
}
.photo {
  width: 100%;
  height: 100%;
}
.photo-wrap {
  width: 68px;
  height: 68px;
  border: 1px solid #93c5fd;
  background: #eff6ff;
}
.photo {
  object-fit: cover;
  display: block;
}
.section {
  margin-top: 7px;
}
.section-title {
  margin: 0 0 4px;
  font-size: 14.2pt;
  font-weight: 700;
  color: var(--heading);
}
.summary {
  margin: 0;
  text-align: left;
  font-size: 10.05pt;
}
.item {
  margin-bottom: 5px;
}
.work-item-keep {
  width: 100%;
  display: block;
  margin-bottom: 5px;
  break-inside: avoid;
  page-break-inside: avoid;
}
